# Build the reviewed application-owned XLSX asset from the TypeScript column manifest.
# Usage: pnpm exec tsx scripts/build-customer-workflow-template.ts
from pathlib import Path
import json
import sys
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Protection
from openpyxl.worksheet.table import Table, TableStyleInfo
from openpyxl.worksheet.datavalidation import DataValidation
from openpyxl.formatting.rule import FormulaRule
from openpyxl.comments import Comment
from openpyxl.utils import get_column_letter as letter
from openpyxl.workbook.defined_name import DefinedName
from openpyxl.packaging.custom import StringProperty

root=Path(__file__).resolve().parent.parent
sys.stdin.reconfigure(encoding='utf-8')
columns=json.load(sys.stdin)
book=Workbook(); guide=book.active; guide.title='Start Here'
for name in [*columns,'Reference Lists','Address Lists','Postal Codes','Examples Guide']: book.create_sheet(name)
navy='163E32'; pale='FFF3D6'; gray='F1F4F3'; blue='EAF3F9'; red='FCE4D6'
for sheet in book:
    sheet.sheet_view.showGridLines=False
    sheet.sheet_properties.pageSetUpPr.fitToPage=True
    sheet.sheet_properties.tabColor=navy if sheet.title in columns else 'B4BDB8'
    sheet.sheet_properties.outlinePr.summaryRight=True
    sheet.print_options.horizontalCentered=False

instructions=[
('AFhomes customer import','Fill only your customer records. This file contains no sample customer rows to delete.'),
('1. Start in Customers','One purchase per row. Begin at row 2. Use the column dropdowns and prompts.'),
('2. IDs','Keep an existing ID or leave blank. Proposed VIP ID is calculated from the row. Its row sequence is a comparison only. Official unique IDs are issued by the server on confirmation and can differ.'),
('3. Select the purchase','Choose the VIP tier, approved payment scheme, purchase status and actual contract date.'),
('4. Existing active VIPs','Enter the existing usable Loyalty Stay Points and actual activation/expiry dates. Do not enter a potential lifetime benefit as a balance.'),
('5. Sales Team (when applicable)','Choose the customer link and registered referrer/recommender. Team attribution is validated on the server.'),
('6. Payments (when applicable)','Enter one real payment per row. Keep the date, amount, method and receipt/bank reference. Claimed payments still require the existing review process.'),
('7. Supplementary Holders (Gold only)','Add the supplementary holder only when applicable. Select the same customer link.'),
('8. Optional details','Optional profile columns are grouped to the right. Use Excel outline + to expand them if needed.'),
('9. Review in the system','Upload, review every flag, then download the review workbook. It retains correct and incorrect values and explains what to fix.'),
('10. Correct and upload again','Edit original data cells. The system ignores old review notes and validates again. No customer or official ID is created during validation.'),
('11. Confirm Import','Only explicit confirmation writes eligible records. Invalid records are blocked.'),
('Editable cells','Pale yellow cells accept data. Proposed VIP ID starts as a formula but may be replaced for comparison. Gray review notes are generated by the system.'),
('Dates','Type actual dates as YYYY-MM-DD, for example 1987-10-14. Date validation checks entries; this macro-free workbook does not add a desktop calendar popup.'),
('Numbers and contact details','Phone and ID cells are text so leading zeros are retained. Enter money without a currency symbol or thousands separator.'),
('Customer links','Use the existing VIP ID, Customer ID, or a unique email from Customers. If all are blank, supply an email before adding linked records.'),
('Restrictions','Dropdowns prevent common mistakes. Pasted data is checked again by the server. A locally completed row is not proof of Finance approval.'),
('Capacity','500 prepared rows per input sheet. Keep original headers and worksheet names. Blank rows are ignored.'),
('Privacy','This workbook can contain personal information. Share it only with authorized staff.'),
]
for i,(heading,body) in enumerate(instructions,1):
    guide.cell(i,1,heading);guide.cell(i,2,body)
    guide.cell(i,1).font=Font(name='Arial',size=14 if i==1 else 11,bold=True,color=navy)
    guide.cell(i,2).font=Font(name='Arial',size=11,color='24332C')
    guide.cell(i,2).alignment=Alignment(wrap_text=True,vertical='center')
    guide.row_dimensions[i].height=48 if len(body)>125 else 35
    guide.cell(i,1).alignment=Alignment(wrap_text=True,vertical='center')
guide.column_dimensions['A'].width=30;guide.column_dimensions['B'].width=105
guide.sheet_view.zoomScale=90;guide.print_area='A1:B19'

required={'Customers':{'first_name','last_name','mobile','email','vip_tier','stated_payment_scheme','contract_date'},'Payments':{'customer_key','purpose','amount','date','method'},'Supplementary Holders':{'customer_key','first_name','last_name'},'Sales Team':{'customer_key'}}
options={'vip_tier':'Gold,Silver,Bronze','stated_payment_scheme':'Spot cash,Move a,Installment 4_month,Move b1 40 12,Move b2 25 12','stated_status':'Pending,Reservation,Partial,Full,Active,Inactive,Expired,Suspended,Cancelled','sex':'Male,Female','civil_status':'Single,Married,Widowed,Separated','suffix':'N/A,Jr.,Sr.,II,III,IV','purpose':'Reservation fee,Down payment,Installment,Full payment','method':'Cash,Bank transfer,GCash,Maya,Card,Cheque'}
notes={'customer_id':'Existing Customer ID only. Blank uses the existing server allocator on confirmation.','purchase_reference':'Existing official VIP card ID only. Blank requests a unique server-issued ID on confirmation.','contract_classification':'New issuance is Standard (S). Non-Standard (N) is only for an authorized existing historical ID.','existing_stay_points_total':'Existing usable balance, whole points. Not a new benefit or the lifetime potential total.','stated_regular_price':'Actual agreed price from the source contract. Do not infer or change a historical price.','payment_key':'Optional. Server creates a stable claim reference when blank. Separate identical payments require distinct references.'}
for sheet_name,cols in columns.items():
    sh=book[sheet_name];lookup={c['key']:i+1 for i,c in enumerate(cols)}
    sh.freeze_panes='F2' if sheet_name=='Customers' else 'B2';sh.sheet_view.zoomScale=85
    sh.row_dimensions[1].height=48
    for j,c in enumerate(cols,1):
        head=sh.cell(1,j,c['header']);head.font=Font(name='Arial',size=11,bold=True,color='FFFFFF');head.fill=PatternFill('solid',fgColor=navy);head.alignment=Alignment(wrap_text=True,vertical='center',horizontal='center')
        width=32 if c['key']=='vip_id_preview' else 24 if c['key'] not in ('email','address_line_1','business_address','review_errors','review_warnings') else 42
        sh.column_dimensions[letter(j)].width=width
        if c['key']=='review_status':sh.column_dimensions[letter(j)].width=25
        if sheet_name=='Customers' and c['key'] in {'existing_reservation_reference','address_line_2','postal_code','landline','tin','occupation','business_address','position','sex','citizenship','civil_status','vip_purchase_date','contract_classification'}:sh.column_dimensions[letter(j)].outlineLevel=1;sh.column_dimensions[letter(j)].hidden=True
        comment=notes.get(c['key'], 'Required for this record.' if c['key'] in required[sheet_name] else 'Optional. Leave blank when not applicable; do not enter invented information.')
        head.comment=Comment(comment,'AFhomes')
        if c['disposition']=='calculated': head.comment=Comment('Editable comparison only. You may replace the formula result. To preserve an already issued ID, enter it in VIP card ID. Official sequence assignment remains server-side.' if c['key']=='vip_id_preview' else 'Automatic review output. Upload for authoritative validation and downloadable cell-level notes.','AFhomes')
        date=c['key'] in ['birth_date','date','contract_date','vip_purchase_date','existing_card_activation_date','existing_card_valid_until']
        amount=c['key'] in ['amount','stated_regular_price','stated_discount','stated_rf']
        for r in range(2,502):
            cell=sh.cell(r,j);cell.font=Font(name='Arial',size=11,color='20352B');cell.fill=PatternFill('solid',fgColor=gray if c['disposition']=='calculated' and c['key']!='vip_id_preview' else pale);cell.protection=Protection(locked=c['disposition']=='calculated' and c['key']!='vip_id_preview');cell.alignment=Alignment(vertical='center',horizontal='right' if amount else 'left');cell.number_format='yyyy-mm-dd' if date else '0.00' if amount else '0' if c['key']=='existing_stay_points_total' else '@'
        if c['key'] in options:
            dv=DataValidation(type='list',formula1='"'+options[c['key']]+'"',allow_blank=True)
        elif date:
            comment='Type a real date as YYYY-MM-DD (for example 1987-10-14). This field validates dates; it does not add a desktop calendar popup.'
            head.comment=Comment(comment,'AFhomes')
            dv=DataValidation(type='date',operator='between',formula1='DATE(1900,1,1)',formula2='DATE(2200,12,31)',allow_blank=True)
        elif amount or c['key']=='existing_stay_points_total':dv=DataValidation(type='decimal' if amount else 'whole',operator='between',formula1=0,formula2=1000000000,allow_blank=True)
        elif c['key']=='mobile':
            ref=letter(j)+'2';dv=DataValidation(type='custom',formula1=f'OR({ref}="",AND(LEFT({ref},2)="09",LEN({ref})=11,ISNUMBER(VALUE({ref}))),AND(LEFT({ref},4)="+639",LEN({ref})=13,ISNUMBER(VALUE(RIGHT({ref},12)))))',allow_blank=True)
        else:dv=None
        if dv:
            dv.showInputMessage=True;dv.promptTitle=c['header'][:32];dv.prompt=comment[:255];dv.showErrorMessage=True;dv.errorStyle='stop';dv.errorTitle='Check this value';dv.error='Use a listed option or the date/number format described in the column note.';sh.add_data_validation(dv);dv.add(f'{letter(j)}2:{letter(j)}501')
    status=letter(lookup['review_status']);first=letter(lookup.get('first_name',lookup.get('customer_key',1)))
    mandatory=[letter(lookup[k]) for k in required[sheet_name] if k in lookup]
    for r in range(2,502):
        blank=f'COUNTIF(A{r}:{letter(len(cols)-(4 if sheet_name=="Customers" else 3))}{r},"<>")=0'
        missing='OR('+','.join(f'{c}{r}=""' for c in mandatory)+')'
        sh.cell(r,lookup['review_status'],f'=IF({blank},"",IF({missing},"Check required fields","Ready for system review"))')
        if sheet_name=='Customers':
            vip=letter(lookup['purchase_reference'])+str(r);tier=letter(lookup['vip_tier'])+str(r);scheme=letter(lookup['stated_payment_scheme'])+str(r);classification=letter(lookup['contract_classification'])+str(r)
            date=letter(lookup['contract_date'])+str(r);purchase_date=letter(lookup['vip_purchase_date'])+str(r)
            chosen_date=f'IF({purchase_date}<>"",{purchase_date},{date})'
            date_code=f'IF(ISNUMBER({chosen_date}),TEXT({chosen_date},"yymmdd"),RIGHT(LEFT({chosen_date},4),2)&MID({chosen_date},6,2)&RIGHT({chosen_date},2))'
            prefix=f'{date_code}&IF(LEN({vip})=17,MID({vip},7,5),TEXT(ROW()-1,"00000"))'
            tier_code=f'IF({tier}="Gold","G1",IF({tier}="Silver","S1","B1"))'
            terms=f'IF(OR({scheme}="Spot cash",{scheme}="Move a"),"C01",IF({scheme}="Installment 4_month","T04","T12"))'
            flag=f'IF(OR({classification}="Non-Standard",AND({classification}="",RIGHT({vip},1)="N")),"N","S")'
            sh.cell(r,lookup['vip_id_preview'],f'=IF(OR({tier}="",{scheme}="",AND({date}="",{purchase_date}="")),"",IFERROR({prefix}&{tier_code}&{terms}&{flag},"Check purchase date"))')
    sh.conditional_formatting.add(f'A2:{letter(len(cols))}501',FormulaRule(formula=[f'${status}2="Check required fields"'],fill=PatternFill('solid',fgColor=red)))
    table=Table(displayName={'Customers':'Customers','Supplementary Holders':'SupplementaryHolders','Sales Team':'SalesTeam','Payments':'Payments'}[sheet_name],ref=f'A1:{letter(len(cols))}501');table.tableStyleInfo=TableStyleInfo(name='TableStyleMedium4',showRowStripes=False);sh.add_table(table)
    sh.protection.sheet=True;sh.protection.autoFilter=False;sh.protection.sort=False;sh.protection.selectLockedCells=False;sh.protection.selectUnlockedCells=False
    sh.print_title_rows='1:1';sh.print_area=f'A1:{letter(len(cols))}501'
refs=book['Reference Lists'];refs.append(['SVD','SSM','SM','OST','','Registered staff','Role','AA number','SVD tree','SSM','SM','Contact number','Email','','','Customer links'])
for r in range(2,502):refs.cell(r,16,'')
for name in ['Address Lists','Postal Codes']:book[name].append(['Reference','Value'])
examples=book['Examples Guide'];examples.append(['Field','Example format','Meaning']);examples.append(['VIP card ID','26101400003G1C01S','Illustration only. Do not copy as an issued number.']);examples.append(['Mobile number','09171234567','Text preserves the first zero.']);examples.append(['Contract date','2026-10-14','Year-month-day.']);examples.append(['Money','60000.00','Actual source amount, without currency signs or commas.']);examples.append(['Existing points','10000','Confirmed currently usable balance, not the lifetime entitlement.']);examples.column_dimensions['A'].width=26;examples.column_dimensions['B'].width=28;examples.column_dimensions['C'].width=90
for name in ['Reference Lists','Address Lists','Postal Codes']:book[name].sheet_state='hidden'
book.custom_doc_props.append(StringProperty(name='AFHomesTemplate',value='company_v2'));book.custom_doc_props.append(StringProperty(name='AFHomesMappingVersion',value='7'))
book.calculation.calcMode='auto';book.calculation.fullCalcOnLoad=True;book.calculation.forceFullCalc=True;book.active=0
book.save(root/'packages/contracts/assets/customer-workflow-template.xlsx')
print('Generated clean workbook with',sum(sum(c['disposition']=='input' for c in v) for v in columns.values()),'input columns across four record sheets; 500 prepared rows each.')
